begin;
create table public.test_catalogo (
 catalog_id uuid primary key default gen_random_uuid(),
 code text not null unique,
 kind text not null check(kind in ('protected','custom')),
 active_version_id bigint
);
alter table public.test_bienestar add column catalog_id uuid references public.test_catalogo(catalog_id),
 add column publication_status text not null default 'draft' check(publication_status in ('draft','published')),
 add column scoring_kind text not null default 'sum',
 add column revision integer not null default 1 check(revision>0),
 add column published_at timestamptz;
alter table public.test_bienestar alter column is_active set default false;
alter table public.pregunta_test add column helper text not null default '';
alter table public.test_resultado_nivel add column label text not null default '',add column interpretation text not null default '';
create unique index test_catalog_version_unique on public.test_bienestar(catalog_id,version);
alter table public.test_catalogo add constraint active_version_fk foreign key(active_version_id) references public.test_bienestar(id_test) deferrable initially deferred;
create function private.check_test_parent() returns trigger language plpgsql security invoker set search_path='' as $$
declare parent_id bigint; old_id bigint;
begin
 if tg_table_name='opcion_respuesta' then
  if tg_op<>'DELETE' then select test_id into parent_id from public.pregunta_test where id_pregunta=new.pregunta_test_id_pregunta; end if;
  if tg_op<>'INSERT' then select test_id into old_id from public.pregunta_test where id_pregunta=old.pregunta_test_id_pregunta; end if;
 else
  if tg_op<>'DELETE' then parent_id:=new.test_id; end if;
  if tg_op<>'INSERT' then old_id:=old.test_id; end if;
 end if;
 if exists(select 1 from public.test_bienestar where id_test in(parent_id,old_id) and publication_status='published') then raise exception using errcode='P0422',message='Contenido publicado inmutable';end if;
 if tg_op='DELETE' then return old;else return new;end if;
end;$$;
create function private.check_test_version() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='DELETE' and old.publication_status='published' then raise exception using errcode='P0422',message='Versión publicada inmutable';end if;
 if tg_op='UPDATE' and old.publication_status='published' then
  if (to_jsonb(new)-'is_active'-'revision') is distinct from (to_jsonb(old)-'is_active'-'revision') or new.revision<>old.revision+1 then raise exception using errcode='P0422',message='Versión publicada inmutable';end if;
 end if;
 if tg_op<>'DELETE' then
  if new.publication_status='draft' and (new.is_active or new.published_at is not null) then raise exception using errcode='P0422',message='Borrador no activable';end if;
  if new.publication_status='published' and new.published_at is null then raise exception using errcode='P0422',message='Publicación requiere fecha';end if;
  if exists(select 1 from public.test_catalogo where catalog_id=new.catalog_id and kind='custom') and new.nombre_test in ('WHO-5 · Bienestar','PHQ-9 · Ánimo','GAD-7 · Ansiedad','Sondeo inicial','Escala de Estrés Percibido (PSS-10)') then raise exception using errcode='P0422',message='Nombre reservado';end if;
  return new;
 end if;return old;
end;$$;

do $body$
declare item jsonb;q jsonb;o jsonb;l jsonb; cat uuid;tid bigint;qid bigint;ord integer;existing jsonb;
begin
 for item in select value from jsonb_array_elements($manifest$[{"code": "who5", "title": "WHO-5 · Bienestar", "scoringKind": "who5", "sourceHash": "526546640bb7c3436c7f6ff203741e593c90577b991502f9c3f2f11f671c7b27", "max": 25, "questions": [{"text": "Me he sentido alegre y de buen humor", "helper": "Considera cómo te has sentido durante las últimas dos semanas.", "critical": false, "options": [{"text": "En ningún momento", "score": 0}, {"text": "Rara vez", "score": 1}, {"text": "Algunas veces", "score": 2}, {"text": "A menudo", "score": 3}, {"text": "La mayor parte del tiempo", "score": 4}, {"text": "Todo el tiempo", "score": 5}]}, {"text": "Me he sentido calmado(a) y relajado(a)", "helper": "Considera cómo te has sentido durante las últimas dos semanas.", "critical": false, "options": [{"text": "En ningún momento", "score": 0}, {"text": "Rara vez", "score": 1}, {"text": "Algunas veces", "score": 2}, {"text": "A menudo", "score": 3}, {"text": "La mayor parte del tiempo", "score": 4}, {"text": "Todo el tiempo", "score": 5}]}, {"text": "Me he sentido activo(a) y con energía", "helper": "Considera cómo te has sentido durante las últimas dos semanas.", "critical": false, "options": [{"text": "En ningún momento", "score": 0}, {"text": "Rara vez", "score": 1}, {"text": "Algunas veces", "score": 2}, {"text": "A menudo", "score": 3}, {"text": "La mayor parte del tiempo", "score": 4}, {"text": "Todo el tiempo", "score": 5}]}, {"text": "Me he despertado sintiéndome fresco(a) y descansado(a)", "helper": "Considera cómo te has sentido durante las últimas dos semanas.", "critical": false, "options": [{"text": "En ningún momento", "score": 0}, {"text": "Rara vez", "score": 1}, {"text": "Algunas veces", "score": 2}, {"text": "A menudo", "score": 3}, {"text": "La mayor parte del tiempo", "score": 4}, {"text": "Todo el tiempo", "score": 5}]}, {"text": "Mi vida diaria ha estado llena de cosas que me interesan", "helper": "Considera cómo te has sentido durante las últimas dos semanas.", "critical": false, "options": [{"text": "En ningún momento", "score": 0}, {"text": "Rara vez", "score": 1}, {"text": "Algunas veces", "score": 2}, {"text": "A menudo", "score": 3}, {"text": "La mayor parte del tiempo", "score": 4}, {"text": "Todo el tiempo", "score": 5}]}], "levels": [{"key": "bajo", "label": "Bienestar bajo", "content": "Un puntaje igual o inferior a 50 indica bajo bienestar. Es un buen momento para hacer seguimiento de cómo te sientes.", "min": 0, "max": 12}, {"key": "aceptable", "label": "Bienestar aceptable", "content": "Tu bienestar percibido se encuentra en un nivel aceptable. ¡Sigue cuidando tus hábitos!", "min": 13, "max": 25}]}, {"code": "phq9", "title": "PHQ-9 · Ánimo", "scoringKind": "phq9", "sourceHash": "7bf6b483510ee4790c378267b80c67faf7588e5157eeb9607f05982c1177fb23", "max": 27, "questions": [{"text": "Poco interés o placer en hacer cosas", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Sentirse decaído(a), deprimido(a) o sin esperanzas", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Tener dificultad para quedarse o permanecer dormido(a), o dormir demasiado", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Sentirse cansado(a) o con poca energía", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Tener poco apetito o comer en exceso", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Sentirse mal con usted mismo(a), o que es un fracaso o que ha quedado mal con usted o con su familia", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Tener dificultad para concentrarse en cosas como leer el periódico o ver televisión", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Moverse o hablar tan lento que otra gente podría haberlo notado, o lo contrario: estar tan inquieto(a) que se ha movido mucho más de lo habitual", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Pensamientos de que estaría mejor muerto(a) o de lastimarse de alguna manera", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}], "levels": [{"key": "minimo", "label": "Depresión mínima", "content": "No se registran síntomas depresivos significativos en las últimas dos semanas.", "min": 0, "max": 4}, {"key": "leve", "label": "Depresión leve", "content": "Síntomas depresivos leves. Vale la pena seguir observándote y cuidar tu rutina de descanso.", "min": 5, "max": 9}, {"key": "moderado", "label": "Depresión moderada", "content": "Síntomas depresivos moderados. Conversemos con el área de bienestar para revisar cómo apoyarte.", "min": 10, "max": 14}, {"key": "moderadamente_severo", "label": "Depresión moderadamente severa", "content": "Síntomas depresivos moderadamente severos. Buscar acompañamiento profesional es una buena decisión.", "min": 15, "max": 19}, {"key": "severo", "label": "Depresión severa", "content": "Síntomas depresivos severos. Te recomendamos contactar al área de bienestar estudiantil cuanto antes.", "min": 20, "max": 27}]}, {"code": "gad7", "title": "GAD-7 · Ansiedad", "scoringKind": "gad7", "sourceHash": "cc2a04d044132815c9dac72b0361409e1142557399ba0d3e2a28842a6413e89e", "max": 21, "questions": [{"text": "Sentirse nervioso(a), ansioso(a) o muy alterado(a)", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "No poder impedir o controlar las preocupaciones", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Preocuparse demasiado por diferentes cosas", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Tener dificultad para relajarse", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Sentirse inquieto(a) y tener dificultad para estarse quieto(a)", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Irritarse o enfadarse con facilidad", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "Sentir miedo, como si algo terrible fuera a pasar", "helper": "Durante las últimas dos semanas, ¿con qué frecuencia le han afectado los siguientes problemas?", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}], "levels": [{"key": "minimo", "label": "Ansiedad mínima", "content": "No se registran síntomas de ansiedad significativos en las últimas dos semanas.", "min": 0, "max": 4}, {"key": "leve", "label": "Ansiedad leve", "content": "Síntomas de ansiedad leves. Mantener hábitos de descanso y pausas activas ayuda a mantenerlos a raya.", "min": 5, "max": 9}, {"key": "moderado", "label": "Ansiedad moderada", "content": "Síntomas de ansiedad moderados. Conversemos con el área de bienestar para revisar cómo apoyarte.", "min": 10, "max": 14}, {"key": "severo", "label": "Ansiedad severa", "content": "Síntomas de ansiedad severos. Te recomendamos contactar al área de bienestar estudiantil cuanto antes.", "min": 15, "max": 21}]}, {"code": "sondeo", "title": "Sondeo inicial", "scoringKind": "sondeo", "sourceHash": "ff0a7da0ad311f8c89c7446d6a6a86e80d6689d00372aeca69677e4e4bb75e60", "max": 9, "questions": [{"text": "¿Has tenido poco interés o placer en hacer cosas?", "helper": "Durante las últimas dos semanas", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "¿Te has sentido decaído(a), deprimido(a) o sin esperanzas?", "helper": "Durante las últimas dos semanas", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}, {"text": "¿Te has sentido nervioso(a), ansioso(a) o muy alterado(a)?", "helper": "Durante las últimas dos semanas", "critical": false, "options": [{"text": "Nunca", "score": 0}, {"text": "Varios días", "score": 1}, {"text": "Más de la mitad de los días", "score": 2}, {"text": "Casi todos los días", "score": 3}]}], "levels": [{"key": "sin_alerta", "label": "Sin señales de alerta", "content": "Tus respuestas no muestran señales que ameriten una evaluación adicional hoy.", "min": 0, "max": 9}]}]$manifest$::jsonb) loop
  if (select count(*) from public.test_bienestar where nombre_test=item->>'title' and is_active)>1 then raise exception 'Instrumento ambiguo';end if;
  insert into public.test_catalogo(code,kind) values(item->>'code','protected') returning catalog_id into cat;
  for tid in select id_test from public.test_bienestar where nombre_test=item->>'title' loop
   select jsonb_agg(jsonb_build_object('text',p.texto_pregunta,'helper',item->'questions'->(p.orden-1)->>'helper','critical',p.is_critica,'options',(select jsonb_agg(jsonb_build_object('text',texto_opcion,'score',puntaje) order by id_opcion) from public.opcion_respuesta where pregunta_test_id_pregunta=p.id_pregunta)) order by p.orden) into existing from public.pregunta_test p where test_id=tid;
   if existing is distinct from item->'questions' then raise exception 'Contenido existente incompatible con manifiesto';end if;
   if (select jsonb_agg(jsonb_build_object('key',nivel_resultado,'min',puntaje_minimo,'max',puntaje_maximo) order by puntaje_minimo) from public.test_resultado_nivel where test_id=tid) is distinct from (select jsonb_agg(jsonb_build_object('key',value->>'key','min',value->'min','max',value->'max') order by (value->>'min')::int) from jsonb_array_elements(item->'levels')) then raise exception 'Niveles incompatibles';end if;
  end loop;
  if not exists(select 1 from public.test_bienestar where nombre_test=item->>'title') then
   insert into public.test_bienestar(nombre_test,tipo_test,version,puntaje_maximo,is_active,catalog_id,scoring_kind) values(item->>'title','protected',1,(item->>'max')::int,true,cat,item->>'scoringKind') returning id_test into tid;
   ord:=0;
   for q in select value from jsonb_array_elements(item->'questions') loop
    ord:=ord+1;insert into public.pregunta_test(test_id,test_version,orden,texto_pregunta,helper,is_critica) values(tid,1,ord,q->>'text',q->>'helper',(q->>'critical')::boolean) returning id_pregunta into qid;
    for o in select value from jsonb_array_elements(q->'options') loop insert into public.opcion_respuesta(pregunta_test_id_pregunta,texto_opcion,puntaje) values(qid,o->>'text',(o->>'score')::int);end loop;
   end loop;
   for l in select value from jsonb_array_elements(item->'levels') loop insert into public.test_resultado_nivel(test_id,test_version,nivel_resultado,puntaje_minimo,puntaje_maximo,label,interpretation) values(tid,1,l->>'key',(l->>'min')::int,(l->>'max')::int,l->>'label',l->>'content');end loop;
  end if;
  update public.test_bienestar set catalog_id=cat,publication_status='published',published_at=now(),scoring_kind=item->>'scoringKind' where nombre_test=item->>'title';
  update public.pregunta_test p set helper=item->'questions'->(p.orden-1)->>'helper' where test_id in(select id_test from public.test_bienestar where catalog_id=cat);
  update public.test_resultado_nivel n set label=l.value->>'label',interpretation=l.value->>'content' from jsonb_array_elements(item->'levels') l where n.test_id in(select id_test from public.test_bienestar where catalog_id=cat) and n.nivel_resultado=l.value->>'key';
  update public.test_catalogo set active_version_id=(select id_test from public.test_bienestar where catalog_id=cat and is_active) where catalog_id=cat;
 end loop;
 if (select count(*) from public.test_bienestar where nombre_test='Escala de Estrés Percibido (PSS-10)' and is_active)>1 then raise exception 'PSS-10 ambiguo';end if;
 insert into public.test_catalogo(code,kind) values('pss10','protected') returning catalog_id into cat;
 update public.test_bienestar set catalog_id=cat,publication_status='published',published_at=now(),scoring_kind='pss10' where nombre_test='Escala de Estrés Percibido (PSS-10)';
 update public.test_catalogo set active_version_id=(select id_test from public.test_bienestar where catalog_id=cat and is_active) where catalog_id=cat;
 for item in select jsonb_build_object('title',nombre_test) from public.test_bienestar where catalog_id is null group by nombre_test loop
  if (select count(*) from public.test_bienestar where nombre_test=item->>'title' and is_active)>1 then raise exception 'Catálogo existente ambiguo';end if;
  insert into public.test_catalogo(code,kind) values('legacy_'||gen_random_uuid()::text,'custom') returning catalog_id into cat;
  update public.test_bienestar set catalog_id=cat,publication_status='published',published_at=now() where nombre_test=item->>'title';
  update public.test_catalogo set active_version_id=(select id_test from public.test_bienestar where catalog_id=cat and is_active) where catalog_id=cat;
 end loop;
end;$body$;

alter table public.test_bienestar alter column catalog_id set not null;
create unique index test_one_active_catalog on public.test_bienestar(catalog_id) where is_active;
create trigger freeze_test before insert or update or delete on public.test_bienestar for each row execute function private.check_test_version();
create trigger freeze_questions before insert or update or delete on public.pregunta_test for each row execute function private.check_test_parent();
create trigger freeze_options before insert or update or delete on public.opcion_respuesta for each row execute function private.check_test_parent();
create trigger freeze_levels before insert or update or delete on public.test_resultado_nivel for each row execute function private.check_test_parent();
create function private.freeze_catalog_identity() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if (to_jsonb(new)-'active_version_id') is distinct from (to_jsonb(old)-'active_version_id') then raise exception using errcode='P0422',message='Identidad del catálogo inmutable';end if;return new;
end;$$;
create trigger freeze_catalog before update on public.test_catalogo for each row execute function private.freeze_catalog_identity();
revoke all on function private.check_test_parent(),private.check_test_version(),private.freeze_catalog_identity() from public,anon,authenticated;
grant execute on function private.check_test_parent(),private.check_test_version(),private.freeze_catalog_identity() to service_role;
commit;
